bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
const network=createCreatorTelegramFetch();
const api=createTelegramBotApi({token,fetchImpl:network.fetch,timeoutMs:25000});
const fail=c=>{throw Object.assign(new Error(c),{code:c})};
try{
 const q=await db.query("SELECT b.delivery_key,b.free_message_ids,b.paid_message_id,b.topic_id,l.thumbnail_file_id,l.sample_file_id,l.paid_video_file_id,l.title,l.description,l.price_stars,l.status AS listing_status FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=a.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND b.status='sent'");
 if(q.rowCount!==1)fail('TARGET_RECEIPT_NOT_UNIQUE');
 const r=q.rows[0],ids=r.free_message_ids.map(Number),paid=Number(r.paid_message_id),thread=Number(r.topic_id),chatId=-1002373696859;
 if(ids.length!==2||ids.some(v=>!Number.isSafeInteger(v)||v<=0)||paid<=0||ids.includes(paid))fail('POSTING_IDS_INVALID');
 if(!['published','paused'].includes(r.listing_status)||thread!==Number(e.VIDEOBOT_VIDEO_SALE_THREAD_ID))fail('TOPIC_AND_STATUS_NOT_VERIFIED');
 if(!r.thumbnail_file_id||!r.sample_file_id||!r.paid_video_file_id||!r.title||!Number.isSafeInteger(r.price_stars))fail('MEDIA_SOURCE_NOT_VERIFIED');
 const me=await api('getMe',{});
 if(String(me?.username||'').toLowerCase()!=='createvdobot')fail('BOT_IDENTITY_MISMATCH');
 const media=[
  {type:'photo',media:r.thumbnail_file_id,caption:''},
  {type:'video',media:r.sample_file_id,supports_streaming:true}
 ];
 for(let i=0;i<2;i++){
  const result=await api('editMessageMedia',{chat_id:chatId,message_id:ids[i],media:media[i]});
  if(result?.message_id!==ids[i]||result?.chat?.id!==chatId||
     (result.message_thread_id!=null&&result.message_thread_id!==thread)||
     !result.media_group_id)fail('ALBUM_EDIT_NOT_CONFIRMED_'+i);
  if(result.has_media_spoiler===true)fail('ALBUM_SPOILER_STILL_SET_'+i);
  console.log('ALBUM_FREE_MEDIA_EDITED_AND_CONFIRMED_'+i+'=PASS');
 }
 console.log('NATIVE_PAID_VIDEO_AND_BUYER_RECEIPTS_UNCHANGED=PASS');
 console.log('NO_REPOST_OR_DELETE=PASS');
}catch(err){
 console.error('VISIBLE_FREE_ALBUM_REPAIR='+String(err.code||'SAFE_STOP'));
 process.exitCode=1;
}finally{await network.close();await db.end();}
JS
